  "onions": {
    "varieties": [
      {
        "name": "Intermediate-day type",
        "zones": [
          "western-cape",
          "southern-cape"
        ],
        "season": "Central & southern regions, coastal areas",
        "maturity": null,
        "traits": "Longer day-length requirement",
        "type": null,
        "sources": [
          {
            "quote": "Others, such as Australian Brown and Caledon Globe, have a longer day-length requirement which can be met only in areas south of latitude 28°S. These are known as late or intermediate-day cultivars, and are grown commercially, mainly in the Eastern and Western Provinces. While they can theoretically be grown in KZN for maturity in mid-summer, quality would tend to be poor because of the normal summer rains.",
            "url": null,
            "doc": "Onion chapter, KwaZulu-Natal Department of Agriculture and Rural Development (KZN DARD) vegetable production guide, chapter 27",
            "page": 1
          }
        ]
      },
      {
        "name": "Texas Grano 502 PPR",
        "zones": [
          "midlands-mistbelt",
          "highveld",
          "lowveld-bushveld",
          "subtropical-coast"
        ],
        "season": "Sown Feb-Apr, transplanted May-Jun, harvested early Sep-early Nov (KZN seedbed method)",
        "maturity": "early",
        "traits": "Short-day cultivar; one of the most popular in KZN",
        "type": null,
        "sources": [
          {
            "quote": "Cultivars such as Texas Grano, Granex 33 and Pyramid have a fairly short day length requirement and are referred to as early or short-day cultivars. For these types the daylight hours in all areas of South Africa become long enough to initiate bulbing.",
            "url": null,
            "doc": "Onion chapter, KZN DARD vegetable production guide, chapter 27",
            "page": 1
          },
          {
            "quote": "Early cultivars are preferred for planting in KZN. Texas Grano 502 PPR, Granex 33 and Pyramid are the most popular cultivars, with the latter two possibly the most important for potential commercial growers.",
            "url": null,
            "doc": "Onion chapter, KZN DARD vegetable production guide, chapter 27",
            "page": 2
          }
        ]
      },
      {
        "name": "Granex 33",
        "zones": [
          "midlands-mistbelt",
          "highveld",
          "lowveld-bushveld",
          "subtropical-coast"
        ],
        "season": "Same seedbed timing as Texas Grano 502 PPR",
        "maturity": "early",
        "traits": "Short-day cultivar; rated by KZN DARD as one of the two most important for potential commercial growers in the province",
        "type": null,
        "sources": [
          {
            "quote": "Early cultivars are preferred for planting in KZN. Texas Grano 502 PPR, Granex 33 and Pyramid are the most popular cultivars, with the latter two possibly the most important for potential commercial growers.",
            "url": null,
            "doc": "Onion chapter, KZN DARD vegetable production guide, chapter 27",
            "page": 2
          }
        ]
      },
      {
        "name": "Pyramid",
        "zones": [
          "midlands-mistbelt",
          "highveld",
          "lowveld-bushveld",
          "subtropical-coast"
        ],
        "season": "Also the standard cultivar used for growing onion 'sets' (sown Aug-Sep, harvested ~December, replanted the following February)",
        "maturity": "early",
        "traits": "Short-day cultivar; dual-purpose — normal bulb crop or grown for sets",
        "type": null,
        "sources": [
          {
            "quote": "The cultivar Pyramid is often used for this purpose, although other cultivars may be suitable. Seed is sown in the normal fashion in open seedbeds, but in August or September rather than the February to March period.",
            "url": null,
            "doc": "Onion chapter, KZN DARD vegetable production guide, chapter 27",
            "page": 3
          }
        ]
      },
      {
        "name": "Australian Brown",
        "zones": [
          "western-cape",
          "southern-cape"
        ],
        "season": "Matures December-January; source explicitly says NOT generally recommended for KZN",
        "maturity": "late",
        "traits": "Intermediate-day cultivar; better keeping quality than early cultivars, but source calls it not generally recommended even where day-length allows it, because it matures during the rainy season in summer-rainfall regions",
        "type": null,
        "sources": [
          {
            "quote": "Late cultivars such as Australian Brown and Caledon Globe are not generally recommended. They have inherently better keeping-quality than most early cultivars, but rains in November to January, when they would be maturing, or being harvested or cured, would detrimentally affect this.",
            "url": null,
            "doc": "Onion chapter, KZN DARD vegetable production guide, chapter 27",
            "page": 2
          }
        ]
      },
      {
        "name": "Caledon Globe",
        "zones": [
          "western-cape",
          "southern-cape"
        ],
        "season": "Matures December-January",
        "maturity": "late",
        "traits": "Intermediate-day cultivar; better keeping quality than early cultivars",
        "type": null,
        "sources": [
          {
            "quote": "Others, such as Australian Brown and Caledon Globe, have a longer day-length requirement which can be met only in areas south of latitude 28°S... grown commercially, mainly in the Eastern and Western Provinces.",
            "url": null,
            "doc": "Onion chapter, KZN DARD vegetable production guide, chapter 27",
            "page": 1
          }
        ]
      }
    ],
    "zoneAdvice": {
      "midlands-mistbelt": {
        "text": "This is the actual KZN DARD source zone: short-day cultivars (Texas Grano 502 PPR, Granex 33, Pyramid) are preferred; intermediate-day types are explicitly discouraged here even though day-length may permit them, because summer rains during maturation/curing spoil bulb quality. High humidity and hail are also flagged as extra local risks.",
        "sources": [
          {
            "quote": "The climate of most of KZN is not really suitable for large-scale commercial production of onions. Production for own use, or for limited local sales, is, however, viable.",
            "url": null,
            "doc": "Onion chapter, KZN DARD vegetable production guide, chapter 27",
            "page": 1
          }
        ]
      },
      "karoo-arid": {
        "text": "Mostly north of 28°S depending on exact location — short-day cultivars are the safer default; the source separately names Oxyfluorfen (Goal) herbicide timing as specific to 'the Karoo region', which at least confirms onions are grown there, but does not name a Karoo-specific cultivar.",
        "sources": [
          {
            "quote": "Oxyfluorfen (Goal) as a pre-emergent in the Karoo region at the 3 to 4 leaf stage and a post-emergent in the summer-rainfall regions at the 2 leaf stage.",
            "url": null,
            "doc": "Onion chapter, KZN DARD vegetable production guide, chapter 27",
            "page": 4
          }
        ]
      }
    }
  },
